create table if not exists public.agent_runs (id uuid primary key default gen_random_uuid(), conversation_id uuid references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, agent_id text not null references public.agent_profiles(id), status text not null default 'running' check(status in ('running','completed','failed')), latency_ms integer, usage jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists agent_runs_conversation_idx on public.agent_runs(conversation_id,created_at);
alter table public.agent_runs enable row level security; drop policy if exists agent_runs_owner on public.agent_runs; create policy agent_runs_owner on public.agent_runs for all using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.evaluations add column if not exists citation_score smallint check(citation_score between 0 and 5);
alter table public.evaluations add column if not exists argument_score smallint check(argument_score between 0 and 5);
alter table public.evaluations add column if not exists originality_score smallint check(originality_score between 0 and 5);
alter table public.evaluations add column if not exists institution_rubric text default 'APA-7';
create table if not exists public.metadata_capabilities (id uuid primary key default gen_random_uuid(), schema_id uuid not null references public.metadata_schemas(id) on delete cascade, capability text not null, config jsonb not null default '{}'::jsonb, enabled boolean not null default true, created_at timestamptz not null default now(), unique(schema_id,capability));
alter table public.metadata_capabilities enable row level security; drop policy if exists metadata_capabilities_owner on public.metadata_capabilities; create policy metadata_capabilities_owner on public.metadata_capabilities for all using(exists(select 1 from public.metadata_schemas s where s.id=schema_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.metadata_schemas s where s.id=schema_id and s.owner_id=auth.uid()));
